const tabId = 730410078;
const urlsToCheck = [
  "https://imgur.com/memegen",
  "https://imgur.com/memegen/create",
  "https://imgur.com/upload",
  "https://imgur.com/beta/meme"
];
const results = await browserjs(tabId, async (urls) => {
  const out = [];
  for (const u of urls) {
    try {
      const res = await fetch(u, { method: "HEAD" });
      out.push({ url: u, status: res.status, resUrl: res.url });
    } catch(e) {
      out.push({ url: u, error: e.message });
    }
  }
  return out;
}, urlsToCheck);
console.log(JSON.stringify(results, null, 2));

