const tabId = 730410078;
// Use CDP to find all textarea, input, or contenteditable elements in all frames
const doc = await tool.cdp({
  tabId,
  method: "DOM.getFlattenedDocument",
  params: { depth: -1, pierce: true }
});

const nodes = doc.nodes || [];
const editableNodes = [];
for (const node of nodes) {
  if (node.nodeName === 'TEXTAREA' || node.nodeName === 'INPUT' || (node.attributes && node.attributes.includes('contenteditable'))) {
    editableNodes.push({
      nodeId: node.nodeId,
      nodeName: node.nodeName,
      attributes: node.attributes
    });
  }
}
console.log("Editable nodes:", JSON.stringify(editableNodes, null, 2));

